using System;
using Exoduser.UnityPort.Core;

namespace Exoduser.UnityPort.Vfx
{
    // Druid (remodel) slam body VFX: every number of the "slam" row of docs/5.1임펙트디자인/DRUID_V81_SKILL_VFX_G1_20261104.md §1 / §2 (2), as pure functions.
    // Textured version (G2 FAIL rework, 11-04): the vector ring and polyline cracks are gone. Body = the Blender earth sheets in Resources/Art/vfx/boss/earth
    // (earth_dust_burst 6x4 / debris_chunks 4x4 / ground_crack_radial*), measured per frame in DruidEarthSheetTable (generated by tools/vfx/import_druid_earth.py).
    // No Unity types and no Core writes: the view (DruidSkillVfxView) only asks "what is drawn at act tick N". Clock = Core ticks since the bossSlam state began
    // (act 0), so pause, restart and frame stepping cannot consume the effect. The damage check is act +6 (DruidRemodelData.SlamActive): the visible edge of the
    // dust burst reaches the Core radius (DruidRemodelData.SlamRadius = 260) on exactly that tick. Lengths are Core px (1 px = 0.754 screen px across the floor at 1080p, 34 deg).
    public static class DruidSlamVfxTimeline
    {
        public const int ActTicks = DruidRemodelData.SlamActive;             // bossSlam state length; the damage check runs when it hits 0 = act +6
        public const double HitRadius = DruidRemodelData.SlamRadius;         // Core hit radius
        public const int WindLiftTicks = 12;                                  // last 12 ticks of bossSlamWind: earth chunks lift
        public const double HeroH = 131;                                      // hero display height 1.31 u = 131 Core px (G1 1.1)
        public const double ScreenPerCorePx = 0.754;                          // floor width, 1 Core px in 1080p screen px
        public const double ScreenPerCorePxVertical = 0.684;                  // billboard height (68.4 px per world unit)

        // colours that stay: the contact core only (the earth sheets keep their own colours)
        public const uint CoreHot = 0xFFF4D0, CoreEdge = 0xD49A5C;

        static double EaseOut(double t) { t = Math.Max(0, Math.Min(1, t)); return 1 - (1 - t) * (1 - t); }

        // ---- contact core: act 0 at the staff tip, 1.2 H, additive HDR, peak scale at +2, 5 ticks, alpha 1 -> .225 (20 % of life) -> 0; _Opacity peak 2.4 so the bloom threshold (1.1) catches it ----
        public const int CoreLife = 5, CorePeakAct = 2;
        public const double CoreDiameter = 1.2 * HeroH, CoreAlphaPeak = 1.0, CoreHdrGain = 1.6;
        public static double CoreAlpha(double age)
        {
            if (age < 0 || age >= CoreLife) return 0;
            double f = age / CoreLife;
            return f < .2 ? 1 - f / .2 * .775 : .225 * (1 - (f - .2) / .8);
        }
        // Soft warm core texture (r = 0 centre .. 1 sprite edge): alpha (1 - r)^2.2, exactly 0 from r .95 (no hard rim); colour baked into the texture
        // (centre #fff4d0 -> amber #d49a5c at r .5, amber beyond). Same rule as the enemy-hit core (vfx-soft-core brief). The old glow texture saturated to a hard white ball at _Opacity 2.4.
        public const double CoreTexCutoff = .95, CoreTexExponent = 2.2, CoreTexMidR = .5;
        public static double CoreTexAlpha(double r) { return r >= CoreTexCutoff ? 0 : Math.Pow(1 - Math.Max(0, r), CoreTexExponent); }
        public static uint CoreTexColor(double r) { return r >= CoreTexMidR ? CoreEdge : Lerp(CoreHot, CoreEdge, r / CoreTexMidR); }
        // the value written to KiSlashAdditive _Opacity (rgb * a * _Opacity): 1.6 at the peak (only the centre passes the bloom threshold 1.1)
        public static double CoreOpacity(double age) { return CoreAlpha(age) * CoreHdrGain; }
        public static double CoreScale(double age)
        {
            if (age < 0 || age >= CoreLife) return 0;
            return age <= CorePeakAct ? .55 + .45 * age / CorePeakAct : 1 - .3 * (age - CorePeakAct) / (CoreLife - CorePeakAct);
        }
        public static uint CoreColor(double age)
        {
            double f = Math.Max(0, Math.Min(1, age / CoreLife));
            return Lerp(CoreHot, CoreEdge, f);
        }

        // ---- shock dust: earth_dust_burst (24 frames, 34 deg render), a camera-facing sprite on the centre. The sprite size is fixed; the visible (alpha) width of the
        // frame played at +6 is set to the hit circle's width (Core 520 px), so the dust edge touches r260 on the damage tick and the later frames spread a little past it. ----
        public const int DustMainLife = 36;                                   // 24 frames over 0.6 s
        public const double DustMainAlphaPeak = .6, DustSmallAlphaPeak = .5;
        public static int DustFrame(double age, double life)
        {
            return Math.Max(0, Math.Min(DruidEarthSheetTable.Frames - 1, (int)Math.Floor(age / life * DruidEarthSheetTable.Frames)));
        }
        // Core px side of the main dust sprite: visible width of the +6 frame = 2 * HitRadius
        public static double DustMainSize { get { return 2 * HitRadius / DruidEarthSheetTable.Width[DustFrame(ActTicks, DustMainLife)]; } }
        // visible horizontal radius (Core px) of a dust sprite of `size` at `frame`
        public static double DustVisibleRadius(double size, int frame) { return size * DruidEarthSheetTable.Width[frame] / 2; }
        public static double DustMainRadius(double act) { return DustVisibleRadius(DustMainSize, DustFrame(act, DustMainLife)); }
        public static double DustMainAlpha(double age)
        {
            if (age < 0 || age >= DustMainLife) return 0;
            double rise = Math.Min(1, (age + 1) / 2.0), fall = age > DustMainLife - 10 ? (DustMainLife - age) / 10.0 : 1;
            return DustMainAlphaPeak * rise * fall;
        }

        // 2..3 small bursts on the circle edge, staggered +2..+5 ticks (the ring feel); same sheet, 300 Core px sprite
        public sealed class RingDust { public int SpawnAct, Life; public double X, Y, Size; }
        public const int RingDustCount = 3, RingDustLife = 28;
        public const double RingDustSize = 300, RingDustRadius = HitRadius * .82;
        static readonly int[] RingDustAct = { 2, 4, 5 };
        public static RingDust[] RingDusts(int seed)
        {
            var rng = new Random(unchecked(seed ^ 0x1B3F77)); var res = new RingDust[RingDustCount]; double start = rng.NextDouble() * Math.PI * 2;
            for (int i = 0; i < RingDustCount; i++)
            {
                double a = start + Math.PI * 2 * (i + rng.NextDouble() * .5) / RingDustCount;
                res[i] = new RingDust { SpawnAct = RingDustAct[i], Life = RingDustLife, X = Math.Cos(a) * RingDustRadius, Y = Math.Sin(a) * RingDustRadius, Size = RingDustSize };
            }
            return res;
        }
        public static double RingDustAlpha(RingDust d, double age)
        {
            if (age < 0 || age >= d.Life) return 0;
            return DustSmallAlphaPeak * Math.Min(1, (age + 1) / 2.0) * (age > d.Life - 8 ? (d.Life - age) / 8.0 : 1);
        }

        // ---- crack decal: ground_crack_radial (variant chosen by the seed, seed rotation), projected on the floor. The decal is scaled so the farthest visible crack pixel
        // reaches the Core hit radius (diameter 520). It opens from the centre during act 0 -> +6 (scale 0 -> 1: the shader has no radial mask property), is kept 3.0 s,
        // last 1 s fades, alpha <= .42. ----
        public const int DecalLife = 180, DecalFade = 60;                     // act +6 .. +186
        public const double DecalAlphaPeak = .42;
        // Flat fallback (no floor projection: the 2D arena, or a 3D field without the receiver): the crack sheet is dark brown (mean rgb 37,27,18) on dark soil and vanished at .42, so alpha x2, <= .85
        public const double FlatAlphaGain = 2.0, FlatAlphaMax = .85;
        public static double CrackAlphaFlat(double act) { return Math.Min(FlatAlphaMax, CrackAlpha(act) * FlatAlphaGain); }
        public const int CrackVariants = 4;
        public static int CrackVariant(int seed) { return (int)unchecked(((uint)seed * 2654435761u) >> 28) % CrackVariants; }
        public static double CrackAngle(int seed) { return new Random(unchecked(seed * 7919 + 101)).NextDouble() * Math.PI * 2; }
        // side of the decal quad in Core px at full reveal
        public static double CrackSize(int variant) { return 2 * HitRadius * (DruidEarthSheetTable.CrackSheetPx / 2.0) / DruidEarthSheetTable.CrackMaxR[variant]; }
        // reach of the farthest visible crack pixel (Core px from the centre) at full reveal
        public static double CrackReachFull(int variant) { return CrackSize(variant) * DruidEarthSheetTable.CrackMaxR[variant] / DruidEarthSheetTable.CrackSheetPx; }
        public static double CrackReveal(double act)
        {
            if (act <= 0) return 0;
            return act >= ActTicks ? 1 : EaseOut(act / ActTicks);
        }
        public static double CrackAlpha(double act)
        {
            double end = ActTicks + DecalLife;
            if (act <= 0 || act >= end) return 0;
            double rise = Math.Min(1, act / 4.0), fade = act > end - DecalFade ? (end - act) / DecalFade : 1;
            return DecalAlphaPeak * rise * fade;
        }

        // ---- debris: debris_chunks 16 stills (4x4 of 128 px), 10..14 flying outward during act 0..+6, 0.2..0.35 s, normal blend, colours as in the sheet ----
        public sealed class Debris
        {
            public int SpawnAct, Life, Frame; public double Angle, Reach, Size, Lift, Spin, Phase;
        }
        public const double DebrisAlphaPeak = .85;
        // visible chunk fraction of its 128 px cell over the 16 stills (measured 0.586 .. 0.797)
        // r2 (G2 FAIL: too small to see): visible chunk 14..30 screen px, so the cell is 23.9 .. 37.6 px; the first 4 ticks are x1.3 brighter
        public const double DebrisFillMin = .586, DebrisFillMax = .797, DebrisCellMinScreen = 23.9, DebrisCellMaxScreen = 37.6, DebrisVisMinScreen = 14, DebrisVisMaxScreen = 30;
        public const int DebrisBrightTicks = 4; public const double DebrisBrightGain = 1.3;
        public static double DebrisBright(double age) { return age >= 0 && age < DebrisBrightTicks ? DebrisBrightGain : 1; }
        public const int DebrisFrames = 16;
        public static double DebrisCellCore(double u) { return (DebrisCellMinScreen + (DebrisCellMaxScreen - DebrisCellMinScreen) * u) / ScreenPerCorePx; }
        public static Debris[] Debrises(int seed)
        {
            var rng = new Random(unchecked(seed ^ 0x51ED2B));
            // 9..11 stills (G1 said 10..14: with the main dust, 3 rim dusts and the 24-sprite / 2-new-per-tick caps, 11 is what fits the act 0..+6 window beside the rim dusts)
            int n = 9 + rng.Next(3); var res = new Debris[n]; double start = rng.NextDouble() * Math.PI * 2;
            var room = new int[ActTicks + 1]; for (int t = 0; t <= ActTicks; t++) room[t] = 2;
            foreach (int a in RingDustAct) room[a]--;
            for (int i = 0; i < n; i++)
            {
                int act = i * (ActTicks + 1) / n;   // the wanted tick; the first tick with room at or after it (else before it)
                int t2 = act; while (t2 <= ActTicks && room[t2] <= 0) t2++;
                if (t2 > ActTicks) { t2 = act; while (t2 > 0 && room[t2] <= 0) t2--; }
                room[t2]--; act = t2;
                res[i] = new Debris
                {
                    SpawnAct = act, Life = 12 + rng.Next(10), Frame = rng.Next(DebrisFrames),
                    Angle = start + Math.PI * 2 * (i + rng.NextDouble() * .8) / n, Reach = 90 + rng.NextDouble() * 80,
                    Size = DebrisCellCore(rng.NextDouble()), Lift = 30 + rng.NextDouble() * 40, Spin = (rng.NextDouble() - .5) * .6, Phase = rng.NextDouble() * Math.PI * 2
                };
            }
            return res;
        }
        // age = ticks since this chunk spawned
        public static double DebrisTravel(Debris s, double age) { return s.Reach * EaseOut(age / s.Life); }
        public static double DebrisHeight(Debris s, double age) { double u = Math.Max(0, Math.Min(1, age / s.Life)); return s.Lift * 4 * u * (1 - u); }
        public static double DebrisRotation(Debris s, double age) { return s.Phase + s.Spin * age; }
        public static double DebrisAlpha(Debris s, double age)
        {
            if (age < 0 || age >= s.Life) return 0;
            double u = age / s.Life; return DebrisAlphaPeak * Math.Min(1, (age + 1) / 2.0) * (u < .55 ? 1 : 1 - (u - .55) / .45);
        }

        // ---- low earth dust (remainder): 4 small earth_dust_burst sprites, 0.5..0.65 s, diameter 0.6..0.9 H, alpha <= .5, visible top <= 0.4 H ----
        public sealed class Puff
        {
            public int SpawnAct, Life; public double X, Y, Size, Peak, LiftPeak, AlphaMul;
        }
        public const int DustCount = 4;
        public const double DustAlphaMax = .5, DustTopMax = .4 * HeroH, DustVisibleHeightFraction = .40;   // visible alpha height of the sheet frames <= .40 of the sprite side (measured .35 .. .36)
        public static Puff[] Dust(int seed)
        {
            var rng = new Random(unchecked(seed ^ 0x2D7F11)); var res = new Puff[DustCount]; double start = rng.NextDouble() * Math.PI * 2;
            for (int i = 0; i < DustCount; i++)
            {
                double a = start + Math.PI * 2 * (i + rng.NextDouble() * .7) / DustCount, r = HitRadius * (.45 + rng.NextDouble() * .55);
                res[i] = new Puff
                {
                    SpawnAct = ActTicks + 1 + i * 2, Life = 30 + rng.Next(9), X = Math.Cos(a) * r, Y = Math.Sin(a) * r,
                    Size = (.6 + .3 * rng.NextDouble()) * HeroH, Peak = .30 + rng.NextDouble() * .15, LiftPeak = 6 + rng.NextDouble() * 8, AlphaMul = 1
                };
            }
            return res;
        }
        public static double DustAlpha(Puff p, double age)
        {
            if (age < 0 || age >= p.Life) return 0;
            return p.Peak * p.AlphaMul * (age < 4 ? age / 4.0 : Math.Pow((p.Life - age) / (p.Life - 4.0), 1.5));
        }
        public static double DustLift(Puff p, double age) { return p.LiftPeak * EaseOut(age / p.Life); }
        public static double DustTop(Puff p, double age) { return DustLift(p, age) + p.Size * DustVisibleHeightFraction / 2; }

        // ---- wind-up (last 12 ticks of bossSlamWind): 6 debris stills inside the circle bob 1..3 screen px ----
        public sealed class Chunk { public double X, Y, Angle, Size, Phase; public int Frame; }
        public const int ChunkCount = 6;
        public static Chunk[] Chunks(int seed)
        {
            var rng = new Random(unchecked(seed ^ 0x6A3C95)); var res = new Chunk[ChunkCount]; double start = rng.NextDouble() * Math.PI * 2;
            for (int i = 0; i < ChunkCount; i++)
            {
                double a = start + Math.PI * 2 * (i + rng.NextDouble() * .6) / ChunkCount, r = 70 + rng.NextDouble() * 160;
                res[i] = new Chunk { X = Math.Cos(a) * r, Y = Math.Sin(a) * r, Angle = (rng.NextDouble() - .5) * 1.0, Size = DebrisCellCore(rng.NextDouble()), Phase = rng.NextDouble() * Math.PI * 2, Frame = rng.Next(DebrisFrames) };
            }
            return res;
        }
        // windAge 0..11 = ticks since St2 first <= 12. Lift in 1080p screen px, always within 1..3 while active.
        public static bool ChunkActive(double windAge) { return windAge >= 0 && windAge < WindLiftTicks; }
        public static double ChunkLiftPx(Chunk c, double windAge) { return 2 + Math.Sin(windAge * .9 + c.Phase); }
        public static double ChunkLiftCore(Chunk c, double windAge) { return ChunkLiftPx(c, windAge) / ScreenPerCorePxVertical; }
        public static double ChunkAlpha(double windAge) { return ChunkActive(windAge) ? DebrisAlphaPeak * Math.Min(1, (windAge + 1) / 3.0) : 0; }

        // deterministic seed from Core ticks and the boss position
        public static int Seed(int tick, double x, double y)
        {
            unchecked
            {
                int h = 17; h = h * 31 + tick; h = h * 31 + (int)Math.Round(x); h = h * 31 + (int)Math.Round(y);
                h ^= h >> 13; h *= 0x5bd1e995; return h ^ (h >> 15);
            }
        }

        public static uint Lerp(uint a, uint b, double t)
        {
            t = Math.Max(0, Math.Min(1, t)); uint c = 0;
            for (int s = 16; s >= 0; s -= 8) { double ca = (a >> s) & 0xFF, cb = (b >> s) & 0xFF; c |= (uint)Math.Round(ca + (cb - ca) * t) << s; }
            return c;
        }
    }
}
